O = {
"c282:xo50_1_20": ("**척수소뇌로**가 전하는 것", "척수소뇌로는 의식하지 못하는 **고유감각**을 소뇌로 보내요. 통증·온도는 **척수시상로**가 대뇌(시상)로 보내요.", "**척수시상로**는 통증과 온도감각을 대뇌로 전한다.", "아프고 뜨거운 건 척수시상로, 소뇌로 가는 건 고유감각", 4),
"c283:xo53_1_18": ("삼차신경 **눈신경가지**의 기능", "눈신경가지(V1)는 이마·각막 등의 **감각**을 맡아요. 시각은 **시각신경(II)** 이 담당해요.", "삼차신경 눈신경가지는 **감각**을 담당한다(시각은 시각신경).", "눈신경은 감각, 보는 건 시각신경", 3),
"c283:xt53_1_18": ("**삼차신경**의 운동 기능", "삼차신경은 얼굴 감각과 함께 아래턱신경(V3)으로 **씹기근육**을 지배하는 가장 큰 혼합 뇌신경이에요.", "'표정근 지배'로 바꾸면 틀려요. 표정근은 얼굴신경이에요.", "씹기는 삼차, 표정은 얼굴", 3),
"c283:xo52_1_22": ("**벌집뼈 체판**을 지나는 신경", "벌집뼈 체판의 작은 구멍들로 **후각신경(I)** 다발이 지나가요. 혀밑신경은 혀밑신경관을 지나요.", "**후각신경**은 벌집뼈 체판을 통과한다.", "체판 = 후각신경", 2),
"c283:xt52_1_22": ("**체판**을 지나는 뇌신경", "코안 위쪽 후각상피의 **후각신경(1번)** 이 벌집뼈 체판 구멍을 지나 후각망울로 가요.", "'혀밑신경'으로 바꾸면 틀려요.", "체판 = 1번 후각", 2),
"c283:xo50_1_21": ("**가쪽곧은근**의 지배신경", "가쪽곧은근은 **갓돌림신경(VI)**, 위빗근은 도르래신경(IV), 나머지 눈근육은 눈돌림신경(III)이 지배해요.", "가쪽곧은근은 **갓돌림신경**이 지배한다.", "LR6 SO4 나머지 3", 3),
"c283:xt50_1_21": ("**아래곧은근** 지배신경", "가쪽곧은근(VI)과 위빗근(IV)을 뺀 나머지 바깥눈근육은 **눈돌림신경(III)** 이 지배해요.", "'갓돌림신경'으로 바꾸면 틀려요. 그건 가쪽곧은근이에요.", "가쪽곧은근·위빗근만 빼면 눈돌림신경", 3),
"c287:xo53_1_14": ("**시각신경**이 지나는 통로", "시각신경은 **시각신경관**을 지나요. 위눈확틈새는 눈돌림·도르래·갓돌림신경과 눈신경가지가 지나는 곳이에요.", "시각신경은 **시각신경관**을 지난다.", "시각신경은 시각신경관, 눈근육 신경은 위눈확틈새", 2),
"c287:xt53_1_14": ("**바깥눈근육** 지배신경", "바깥눈근육은 **눈돌림(III)·도르래(IV)·갓돌림(VI)신경**이 나눠 지배해요.", "'시각신경'을 넣으면 틀려요. 시각신경은 감각(시각)만 해요.", "눈 움직임 = 3·4·6번", 3),
"c284:xo51_1_22": ("**동공 확대**", "동공을 확대하는 것은 **교감신경**이에요. 부교감신경은 동공을 축소해요.", "부교감신경은 동공을 **축소**한다(확대는 교감).", "교감은 싸울 준비(동공 확대), 부교감은 쉬기(축소)", 4),
"c284:xt51_1_22": ("부교감이 늘리는 **소화관 활동**", "부교감신경은 쉬고 소화하는 신경이라 **위창자관 꿈틀운동을 늘려요**.", "'꿈틀운동 감소'로 바꾸면 틀려요. 그건 교감신경이에요.", "부교감 = 소화 촉진", 3),
"c285:xo50_1_22": ("넙다리·폐쇄신경의 **신경얼기**", "넙다리신경과 폐쇄신경은 **허리신경얼기(L1~L4)** 에서 나와요. 엉치신경얼기에서는 궁둥신경이 나와요.", "넙다리신경과 폐쇄신경은 **허리신경얼기**에서 나온다.", "허리얼기 = 넙다리·폐쇄, 엉치얼기 = 궁둥", 4),
"c285:xt50_1_22": ("근육피부·노신경이 나오는 곳", "근육피부신경·노신경·정중신경·자신경·겨드랑신경은 모두 **팔신경얼기(C5~T1)** 에서 나와요.", "'목신경얼기'로 바꾸면 틀려요.", "팔 신경은 팔신경얼기", 3),
"c286:xo53_1_19": ("**파치니소체**의 위치와 기능", "파치니소체는 진피 깊은 곳에서 **진동·깊은 압력**을 감지해요. 표피 바닥층에서 정확한 촉각 위치를 감지하는 것은 **메르켈 원반**이에요.", "**메르켈 원반**은 표피 바닥층에서 정확한 촉각 위치를 감지한다.", "메르켈은 위치, 파치니는 진동", 3),
"c286:xt53_1_19": ("표피 바닥층의 **분별 촉각** 수용기", "**메르켈 원반**은 표피 바닥층에 있어 느리게 적응하며 정확한 위치를 알려 줘요.", "'파치니소체'로 바꾸면 틀려요. 파치니는 진동이에요.", "정확한 위치 = 메르켈", 3),
"c287:xo51_1_12": ("**원근 조절** 구조", "원근은 섬모체근이 **수정체** 두께를 바꿔 조절해요. 홍채는 동공 크기로 빛의 양을 조절해요.", "섬모체근의 수축으로 **수정체**가 원근을 조절한다.", "홍채는 빛의 양, 수정체는 거리", 3),
"c287:xt51_1_12": ("두께를 바꿔 원근 조절", "섬모체근이 수축·이완하면 **수정체**가 두꺼워지거나 얇아져 초점을 맞춰요.", "'홍채'로 바꾸면 틀려요.", "초점 = 수정체", 3),
"c288:xo52_1_12": ("**고막**에 붙은 귓속뼈", "고막에 붙는 것은 **망치뼈**, 안뜰창에 붙는 것은 등자뼈예요.", "**망치뼈**는 고막에 직접 붙어 있다.", "고막–망치–모루–등자–안뜰창", 3),
"c288:xt52_1_12": ("**소리 전달 순서**", "소리는 **고막 → 망치뼈 → 모루뼈 → 등자뼈 → 안뜰창** 순서로 속귀에 전달돼요.", "망치와 등자의 순서를 바꾸면 틀려요.", "망·모·등 순서", 3),
"c288:xo50_1_12": ("**머리 회전** 감지", "머리 회전은 **반고리뼈관**이 감지해요. 달팽이관은 청각을 담당해요.", "**반고리뼈관**은 머리의 회전을 감지한다(달팽이관은 청각).", "달팽이는 듣고, 반고리는 돈다", 4),
"c288:xt50_1_12": ("**각가속도** 감지 구조", "머리 회전(각가속도)은 세 개의 **반고리뼈관** 속 림프 흐름으로 감지해요.", "'달팽이관'으로 바꾸면 틀려요.", "회전 = 반고리뼈관", 3),
"c289:xo51_1_17": ("**칼슘**이 결합하는 곳", "칼슘은 **트로포닌**에 붙고, 그러면 트로포미오신이 비켜나 액틴의 결합 자리가 드러나요.", "칼슘은 **트로포닌**에 결합한다.", "칼슘 → 트로포닌 → 트로포미오신 이동", 3),
"c289:xt51_1_17": ("근육세포질그물에서 나온 **칼슘**", "근육세포질그물에서 나온 칼슘은 **트로포닌**에 붙어 수축을 시작시켜요.", "'트로포미오신'으로 바꾸면 틀려요.", "칼슘은 트로포닌에", 3),
"c289:xo50_1_17": ("근수축 때 **I띠** 변화", "근수축 때 액틴이 미끄러져 들어가 **I띠와 H띠가 짧아지고** A띠(마이오신 길이)는 그대로예요. 맞는 문장이에요.", "'A띠가 짧아진다'고 하면 틀려요.", "A띠는 그대로, I·H띠는 짧아진다", 4),
"c293:xo51_1_9": ("**박출** 때 반달판막", "심실이 피를 내보낼 때 반달판막(대동맥판·허파동맥판)은 **열려요**. 이완기에 닫혀 역류를 막아요.", "심실이 혈액을 내보내는 동안 반달판막은 **열려 있다**.", "박출 때 반달판막 열림, 방실판막 닫힘", 3),
"c293:xt51_1_9": ("**두 첨판**의 방실판막", "왼심방과 왼심실 사이의 **왼방실판막(두갈래판·승모판)** 은 첨판이 두 개예요. 오른쪽은 세갈래판이에요.", "'오른방실판막'으로 바꾸면 틀려요. 오른쪽은 세 개예요.", "왼쪽 2첨(승모판), 오른쪽 3첨", 3),
"c294:xo51_1_20": ("대뇌반구 **안쪽면** 혈액 공급", "대뇌반구 안쪽면은 **앞대뇌동맥**, 가쪽면은 중간대뇌동맥이 공급해요.", "대뇌반구 안쪽면은 **앞대뇌동맥**이 공급한다.", "안쪽면 = 앞대뇌(다리), 가쪽면 = 중간대뇌(팔·얼굴)", 4),
"c294:xt51_1_20": ("대뇌반구 **가쪽면** 혈액 공급", "대뇌반구 가쪽면 대부분(팔·얼굴 운동감각 영역, 언어영역)은 **중간대뇌동맥**이 공급해요.", "'앞대뇌동맥'으로 바꾸면 틀려요.", "가쪽면 = 중간대뇌", 4),
"c294:xo50_1_9": ("허파조직의 **영양혈관**", "허파동맥은 가스교환용(산소 적은 피)이에요. 허파조직 자체에 영양을 주는 것은 **기관지동맥**이에요.", "**기관지동맥**은 허파조직에 산소를 공급하는 영양혈관이다.", "허파동맥은 교환용, 기관지동맥은 영양용", 3),
"c294:xt50_1_9": ("허파조직 자체의 **영양** 동맥", "허파조직에 영양과 산소를 주는 것은 대동맥에서 나온 **기관지동맥**이에요.", "'허파동맥'으로 바꾸면 틀려요.", "영양 = 기관지동맥", 3),
"c295:xo52_1_9": ("**허파정맥**의 혈액", "허파정맥은 허파에서 산소를 받은 **산소가 많은 혈액**을 왼심방으로 날라요. 산소가 적은 혈액은 허파동맥에 흘러요.", "허파정맥은 **산소가 많은** 혈액을 나른다.", "허파정맥 = 동맥혈, 허파동맥 = 정맥혈", 4),
"c295:xt52_1_9": ("**정맥판막**의 역할", "정맥판막은 팔다리 정맥에서 피가 거꾸로 흐르지 않게 막아, 근육 펌프로 피가 심장 쪽으로 올라가게 해요.", "'혈압 상승'처럼 바꾸면 틀려요.", "정맥판막 = 역류 방지", 3),
"c297:xo53_1_10": ("**가스교환** 장소", "가스교환은 **허파꽈리**에서 일어나요. 기관은 공기 통로이고 점막의 술잔세포가 점액을 내 먼지를 붙잡아요.", "가스교환은 **허파꽈리**에서 일어난다.", "기관은 통로, 교환은 허파꽈리", 3),
"c297:xt53_1_10": ("기관 점막의 **점액 분비 세포**", "기관 점막의 **술잔세포**는 점액을 분비해 먼지를 붙잡고, 섬모가 이를 위로 밀어내요.", "'허파꽈리 세포'로 바꾸면 틀려요.", "점액 = 술잔세포", 2),
"c297:xo52_1_10": ("**혀구역**의 위치", "왼허파에는 중간엽이 없고 **왼허파 위엽의 혀구역**이 그 자리를 대신해요.", "혀구역은 **왼허파 위엽**에 있다.", "왼허파 = 2엽(혀구역), 오른허파 = 3엽", 3),
"c297:xt52_1_10": ("**혀구역**이 있는 엽", "**왼허파 위엽**의 아래쪽이 혀처럼 튀어나온 부분이 혀구역이에요.", "'오른허파 중간엽'으로 바꾸면 틀려요.", "혀구역 = 왼허파 위엽", 3),
"c298:xo52_1_13": ("**악성빈혈**의 원인", "악성빈혈은 **비타민 B12 결핍**(내인자 부족)으로 생겨요. 골수가 조혈 능력을 잃은 것은 재생불량빈혈이에요.", "악성빈혈은 **비타민 B12 결핍**으로 생긴다.", "악성 = B12, 재생불량 = 골수", 3),
"c298:xt52_1_13": ("**골수 조혈 능력** 상실", "방사선·약물 등으로 골수가 피를 만들지 못하는 빈혈이 **재생불량빈혈**이에요.", "'악성빈혈'로 바꾸면 틀려요.", "골수가 멈추면 재생불량", 3),
"c298:xo50_1_13": ("**태반**을 통과하는 항체", "태반을 통과하는 항체는 **IgG**예요. IgA는 눈물·침·모유 같은 분비물에서 점막을 지켜요.", "태반을 통과해 태아를 보호하는 항체는 **IgG**다.", "태반은 G, 분비물은 A", 3),
"c298:xt50_1_13": ("**분비물**에 많은 항체", "눈물·침·모유에 많은 것은 **IgA**예요.", "'IgG'로 바꾸면 틀려요. IgG는 태반을 통과해요.", "분비물 = IgA", 3),
"c299:xo53_1_8": ("말초저항과 **혈압**", "혈압 = 심박출량 × 말초저항이라 말초저항이 커지면 혈압은 **올라가요**.", "말초저항이 커질수록 혈압은 **올라간다**.", "저항이 크면 압력이 오른다", 3),
"c299:xt53_1_8": ("혈액 **점도**와 저항", "혈액이 끈끈해질수록(점도 증가) 흐름을 막는 **말초저항이 커져요**.", "'점도가 높으면 저항이 줄어든다'고 하면 틀려요.", "끈끈하면 저항↑", 3),
"c299:xo51_1_13": ("혈장 단백질과 **부종**", "혈장 단백질이 줄면 혈관 안으로 물을 끌어당기는 교질삼투압이 떨어져 액체가 조직에 남아 **부종**이 생겨요. 맞는 문장이에요.", "'혈장 단백질이 늘면 부종이 생긴다'고 하면 틀려요.", "단백질이 줄면 물이 새어 붓는다", 3),
"c299:xo51_1_14": ("**점도**와 혈압", "혈액 점도가 **높아질수록** 저항이 커져 혈압이 올라요. 점도가 낮아지면 혈압은 내려가는 쪽이에요.", "혈액 점도가 **높아지면** 혈압이 오른다.", "점도↑·혈액량↑·혈관 지름↓ = 혈압↑", 3),
"c299:xt51_1_14": ("혈압을 **올리는** 요인", "**말초혈관저항 증가**는 혈압을 올려요(혈압 = 심박출량 × 말초저항).", "'말초혈관저항 감소'로 바꾸면 틀려요.", "저항이 오르면 혈압도 오른다", 3),
"c300:xo53_1_9": ("**투과성**과 부종", "부종은 모세혈관 투과성이 **증가**할 때 생겨요(염증 등). 투과성이 감소하면 액체가 덜 새어 나와요.", "모세혈관 투과성이 **증가**하면 부종이 생긴다.", "부종: 정수압↑, 교질삼투압↓, 투과성↑, 림프 막힘", 3),
"c300:xt53_1_9": ("**부종**의 원인", "모세혈관 **정수압이 높아지면** 액체가 혈관 밖으로 밀려 나가 부종이 생겨요(심부전·정맥 정체).", "'정수압 감소'로 바꾸면 틀려요.", "밀어내는 힘(정수압)↑ = 부종", 3),
"c301:xo53_1_11": ("**허파동맥**의 혈액", "허파동맥은 온몸을 돌고 온 **산소가 적은 혈액**을 허파로 보내요. 산소가 가장 많은 혈액은 허파정맥에 있어요.", "**허파정맥**에는 산소가 가장 많은 혈액이 흐른다.", "허파동맥 = 정맥혈, 허파정맥 = 동맥혈", 4),
"c301:xt53_1_11": ("**산소분압 최고** 혈액", "허파에서 막 산소를 받은 **허파정맥혈**이 산소분압이 가장 높고 이산화탄소분압이 가장 낮아요.", "'허파동맥혈'로 바꾸면 틀려요.", "허파에서 막 나온 피가 산소 최고", 3),
"c301:xo53_1_96": ("**폐활량**의 정의", "안정 날숨 수준에서 최대로 들이쉰 양은 **들숨용량**이에요. 폐활량은 최대 들숨 후 최대 날숨 양이에요.", "안정 날숨 수준에서 최대 들이쉰 양은 **들숨용량**이다.", "들숨용량 = TV + IRV, 폐활량 = IRV + TV + ERV", 3),
"c301:xt53_1_96": ("안정 날숨에서 **최대 들숨**", "안정 날숨 수준(FRC)에서 최대로 들이쉴 수 있는 양이 **들숨용량**(일회호흡량 + 들숨예비량)이에요.", "'폐활량'으로 바꾸면 틀려요.", "들숨용량 = TV + IRV", 3),
"c301:xo52_1_14": ("**기능잔기용량**의 구성", "기능잔기용량은 **날숨예비용적 + 잔기용적**이에요. 들숨예비용적 + 일회호흡용적은 들숨용량이에요.", "들숨예비용적 + 일회호흡용적 = **들숨용량**이다.", "FRC = ERV + RV, IC = IRV + TV", 3),
"c301:xt52_1_14": ("IRV + TV", "들숨예비용적 + 일회호흡용적 = **들숨용량**이에요.", "'기능잔기용량'으로 바꾸면 틀려요.", "IRV + TV = 들숨용량", 3),
"c302:xo53_1_12": ("위주름·위액 분비 층", "위주름을 만들고 위액을 분비하는 것은 가장 안쪽의 **점막**이에요. 장막은 가장 바깥층이에요.", "위 **점막**은 위주름을 만들고 위액을 분비한다.", "분비는 가장 안쪽(점막)", 2),
"c302:xo52_1_11": ("**온쓸개관**이 열리는 곳", "온쓸개관과 이자관은 **샘창자**의 큰샘창자유두로 열려요.", "온쓸개관은 **샘창자**로 열린다.", "쓸개즙·이자액은 샘창자로", 3),
"c302:xo51_1_11": ("**위벽 근육층**", "위는 다른 소화관과 달리 근육층이 **세 층**(속빗·중간돌림·바깥세로)이에요.", "위벽 근육층은 **세 층**(빗·돌림·세로)이다.", "근육 3층이면 위", 3),
"c302:xo50_1_11": ("**식도**가 가로막을 지나는 구멍", "식도는 가로막의 **식도구멍**을 지나요. 대정맥구멍은 아래대정맥이 지나요.", "식도는 가로막의 **식도구멍**을 지나 배안으로 들어간다.", "식도 = 식도구멍, 아래대정맥 = 대정맥구멍", 2),
"c302:xo50_1_15": ("**쓸개즙**을 만드는 곳", "쓸개즙은 **간**에서 만들어지고 쓸개는 저장·농축만 해요.", "쓸개즙은 **간**에서 만들어진다(쓸개는 저장).", "간이 만들고 쓸개가 모은다", 3),
"c303:xo51_1_15": ("**포도당** 흡수 경로", "포도당·아미노산은 융모의 **모세혈관**으로 흡수돼요. 지방은 암죽관(림프)으로 흡수돼요.", "포도당은 **모세혈관**을 거쳐 흡수된다.", "당·아미노산은 혈관, 지방은 암죽관", 3),
"c303:xt51_1_15": ("**암죽관**으로 흡수되는 영양소", "지방은 암죽미립으로 묶여 융모 가운데의 **암죽관(림프)** 으로 흡수돼요.", "'포도당'으로 바꾸면 틀려요.", "지방 = 암죽관", 3),
"c304:xo52_1_15": ("**최종 소변 농도** 결정 부위", "최종 소변 농도는 항이뇨호르몬이 작용하는 **집합관**에서 물 재흡수로 정해져요. 토리쪽곱슬세관은 대부분의 물질을 재흡수해요.", "**집합관**은 최종 소변 농도를 결정한다.", "마지막 농도 = 집합관(ADH)", 3),
"c304:xt52_1_15": ("마지막 **수분 재흡수**", "항이뇨호르몬이 작용하는 **집합관**에서 마지막으로 물을 재흡수해 소변 농도를 정해요.", "'토리쪽곱슬세관'으로 바꾸면 틀려요.", "ADH → 집합관", 3),
"c305:xo51_1_10": ("**다리 림프**가 모이는 곳", "다리와 배 내장의 림프는 **가슴림프관팽대**로 모여 가슴림프관으로 올라가요. 오른림프관은 몸 오른쪽 위만 모아요.", "다리의 림프는 **가슴림프관(팽대)** 으로 모인다.", "오른쪽 위만 오른림프관, 나머지는 가슴림프관", 3),
"c305:xt51_1_10": ("가슴림프관 아래 **팽대부**", "다리와 배 내장의 림프가 모이는 가슴림프관 아래 팽대가 **가슴림프관팽대(암죽조)** 예요.", "'오른림프관'으로 바꾸면 틀려요.", "다리·배 림프 = 암죽조", 2),
"c305:xo50_1_10": ("**가슴림프관**이 들어가는 곳", "가슴림프관은 **왼빗장밑정맥과 왼속목정맥의 합류점(왼정맥각)** 으로 들어가요. 맞는 문장이에요.", "'오른쪽 합류점'이라고 하면 틀려요. 오른쪽은 오른림프관이에요.", "가슴림프관 = 왼정맥각", 3),
"c306:xo53_1_13": ("**코티솔** 분비 부위", "코티솔은 **부신겉질**(다발층)에서 분비돼요. 부신속질은 에피네프린을 분비해요.", "코티솔은 **부신겉질**에서 분비된다.", "겉질은 스테로이드, 속질은 아드레날린", 4),
"c306:xo52_1_16": ("**성장호르몬** 분비 부위", "성장호르몬은 뇌하수체 **앞엽**에서 분비돼요. 뒤엽은 항이뇨호르몬·옥시토신만 분비해요.", "성장호르몬은 뇌하수체 **앞엽**에서 분비된다.", "뒤엽은 둘뿐(항이뇨·옥시토신)", 4),
"c306:xo51_1_16": ("**프로락틴** 분비 부위", "프로락틴은 뇌하수체 **앞엽** 호르몬이에요.", "프로락틴은 뇌하수체 **앞엽** 호르몬이다.", "뒤엽 둘 외에는 앞엽", 3),
"c306:xo50_1_16": ("**베타세포** 호르몬", "이자섬 베타세포는 **인슐린**, 알파세포는 글루카곤을 분비해요.", "이자섬의 **알파세포**는 글루카곤을 분비한다(베타세포는 인슐린).", "알파는 올리고(글루카곤), 베타는 내린다(인슐린)", 3),
}
